wb = load_workbook(fp)
ws = wb.active

def to_rgb(hexargb):
    if not hexargb:
        return None
    return hexargb[-6:].upper()

def is_blue(rgb):
    if not rgb:
        return False
    r = int(rgb[0:2], 16)
    g = int(rgb[2:4], 16)
    b = int(rgb[4:6], 16)
    return (b > 200) and (r < 50) and (g < 180)

map_data = {}
blue = set()
for row in ws.iter_rows():
    for c in row:
        coord = c.coordinate
        rgb = None
        if c.fill and c.fill.fgColor and c.fill.fgColor.rgb:
            rgb = to_rgb(c.fill.fgColor.rgb)
        map_data[coord] = {
            'value': c.value,
            'color': rgb
        }
        if is_blue(rgb):
            blue.add(coord)

print('Total cells:', len(map_data))
print('Blue cells count:', len(blue))
print('Sample A1..I1:', [ (k, map_data[k]['color']) for k in [f'{chr(65+i)}1' for i in range(9)] ])
